def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "neg": 3, "^": 4}

    def apply():
        op = operators.pop()

        if op == "neg":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                raise ValueError("negative exponent")
            result = pow(a, b)
        else:
            if b == 0:
                raise ZeroDivisionError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)

    i = 0
    expecting_operand = True

    try:
        while i < len(expr):
            ch = expr[i]

            if ch.isspace():
                i += 1
                continue

            if "0" <= ch <= "9":
                # Avoid Python's limit on decimal-string-to-int conversion.
                number = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expecting_operand = False
                continue

            if ch == "(":
                operators.append(ch)
                expecting_operand = True
            elif ch == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                expecting_operand = False
            elif ch == "-" and expecting_operand:
                # Prefix minus must not pop a pending power operator.
                operators.append("neg")
            else:
                while (
                    operators
                    and operators[-1] != "("
                    and (
                        precedence[operators[-1]] > precedence[ch]
                        or (
                            precedence[operators[-1]] == precedence[ch]
                            and ch != "^"
                        )
                    )
                ):
                    apply()
                operators.append(ch)
                expecting_operand = True

            i += 1

        while operators:
            apply()

        return values[0]

    except (ZeroDivisionError, ValueError):
        return "error"
